PRAGMA journal_mode=WAL;
PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS polls (ts INTEGER PRIMARY KEY, duration INTEGER NOT NULL, pages INTEGER NOT NULL, streams INTEGER NOT NULL, viewers INTEGER NOT NULL, min_reached INTEGER NOT NULL, remaining INTEGER, errors TEXT NOT NULL DEFAULT '[]');
CREATE TABLE IF NOT EXISTS games (id TEXT PRIMARY KEY, name TEXT NOT NULL, box_art_url TEXT, igdb_id TEXT, first_seen INTEGER NOT NULL, release_date INTEGER, genre TEXT DEFAULT 'Other');
CREATE TABLE IF NOT EXISTS channels (id TEXT PRIMARY KEY, login TEXT NOT NULL, name TEXT NOT NULL, language TEXT NOT NULL, avatar TEXT, created_at INTEGER, first_seen INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS streams (id TEXT PRIMARY KEY, channel_id TEXT NOT NULL REFERENCES channels(id), started_at INTEGER NOT NULL, last_seen INTEGER NOT NULL, ended_at INTEGER, missed INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS samples (ts INTEGER NOT NULL, stream_id TEXT NOT NULL REFERENCES streams(id), viewers INTEGER NOT NULL, game_id TEXT NOT NULL, PRIMARY KEY(ts, stream_id));
CREATE INDEX IF NOT EXISTS samples_game_ts ON samples(game_id, ts);
CREATE TABLE IF NOT EXISTS stream_meta (stream_id TEXT NOT NULL, ts INTEGER NOT NULL, game_id TEXT NOT NULL, title TEXT NOT NULL, tags TEXT NOT NULL, PRIMARY KEY(stream_id,ts));
CREATE INDEX IF NOT EXISTS stream_meta_ts ON stream_meta(ts);
CREATE TABLE IF NOT EXISTS game_hourly (hour INTEGER NOT NULL, game_id TEXT NOT NULL, viewers REAL NOT NULL, channels REAL NOT NULL, coverage REAL NOT NULL, peak REAL NOT NULL, hours_watched REAL NOT NULL, hours_streamed REAL NOT NULL, PRIMARY KEY(hour,game_id));
CREATE TABLE IF NOT EXISTS channel_hourly (hour INTEGER NOT NULL, channel_id TEXT NOT NULL, game_id TEXT NOT NULL, viewers REAL NOT NULL, coverage REAL NOT NULL, peak REAL NOT NULL, sessions INTEGER NOT NULL DEFAULT 1, PRIMARY KEY(hour,channel_id,game_id));
CREATE TABLE IF NOT EXISTS game_daily (day INTEGER NOT NULL, game_id TEXT NOT NULL, viewers REAL NOT NULL, hours_watched REAL NOT NULL, hours_streamed REAL NOT NULL, PRIMARY KEY(day,game_id));
CREATE TABLE IF NOT EXISTS channel_daily (day INTEGER NOT NULL, channel_id TEXT NOT NULL, viewers REAL NOT NULL, hours_watched REAL NOT NULL, PRIMARY KEY(day,channel_id));
CREATE TABLE IF NOT EXISTS game_scan (hour INTEGER NOT NULL, game_id TEXT NOT NULL, channels_total INTEGER NOT NULL, viewers_total INTEGER NOT NULL, median REAL NOT NULL, p75 REAL NOT NULL, p90 REAL NOT NULL, histogram_json TEXT NOT NULL, viewers_json TEXT NOT NULL, PRIMARY KEY(hour,game_id));
CREATE TABLE IF NOT EXISTS clip_weekly (game_id TEXT NOT NULL, week_start INTEGER NOT NULL, top100_views INTEGER NOT NULL, clip_count_sampled INTEGER NOT NULL, top_clip_ids TEXT NOT NULL, PRIMARY KEY(game_id,week_start));
CREATE TABLE IF NOT EXISTS keyword_weekly (week INTEGER NOT NULL, keyword TEXT NOT NULL, channels INTEGER NOT NULL, PRIMARY KEY(week,keyword));
CREATE TABLE IF NOT EXISTS context_events (ts INTEGER NOT NULL, game_id TEXT NOT NULL, type TEXT NOT NULL, title TEXT NOT NULL, url TEXT, source TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS accounts (id TEXT PRIMARY KEY, login TEXT NOT NULL, name TEXT NOT NULL, tokens TEXT NOT NULL, scopes TEXT NOT NULL, bot_enabled INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES accounts(id), expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS changes (id TEXT PRIMARY KEY, account_id TEXT NOT NULL, ts INTEGER NOT NULL, before_json TEXT NOT NULL, after_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS codex_runs (id TEXT PRIMARY KEY, kind TEXT NOT NULL, prompt TEXT NOT NULL, cache_key TEXT NOT NULL, status TEXT NOT NULL, events_json TEXT NOT NULL, output_json TEXT, verified_count INTEGER DEFAULT 0, failed_count INTEGER DEFAULT 0, duration_ms INTEGER DEFAULT 0, est_cost REAL, created_at INTEGER NOT NULL, source TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS codex_cache ON codex_runs(cache_key);
CREATE TABLE IF NOT EXISTS reports (id TEXT PRIMARY KEY, range TEXT NOT NULL, created_at INTEGER NOT NULL, output_json TEXT NOT NULL, source TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS alerts (id TEXT PRIMARY KEY, account_id TEXT NOT NULL, name TEXT NOT NULL, sql TEXT NOT NULL, approved INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS alert_hits (alert_id TEXT NOT NULL, ts INTEGER NOT NULL, data_json TEXT NOT NULL, PRIMARY KEY(alert_id,ts));
CREATE TABLE IF NOT EXISTS blocklist (channel_id TEXT PRIMARY KEY, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS watched_samples (ts INTEGER NOT NULL, channel_id TEXT NOT NULL, viewers INTEGER NOT NULL, game_id TEXT NOT NULL, PRIMARY KEY(ts,channel_id));
CREATE TABLE IF NOT EXISTS job_locks (name TEXT PRIMARY KEY, owner TEXT NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS igdb_metadata (game_id TEXT PRIMARY KEY, release_date INTEGER, genres_json TEXT NOT NULL, themes_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS analysis_usage (owner TEXT NOT NULL, day INTEGER NOT NULL, run_id TEXT NOT NULL, PRIMARY KEY(owner,run_id));
CREATE INDEX IF NOT EXISTS game_hourly_game_hour ON game_hourly(game_id,hour);
CREATE INDEX IF NOT EXISTS channel_hourly_channel_hour ON channel_hourly(channel_id,hour);
CREATE INDEX IF NOT EXISTS streams_channel_started ON streams(channel_id,started_at);
